UPDATE tb_board
SET VIEW_CNT = VIEW_CNT +1
WHERE BOARD_ID =#{boardId}

mapper.select:
SELECT COUNT(*)
FROM tb_board_like
WHERE BOARD_ID = #{boardId}

mapper.delete:
DELETE FROM tb_board_like
WHERE BOARD_ID =#{boardId}
AND EMP_ID = #{empId}

mapper.insert:
SELECT SEQ_BOARD_ID.NEXTVAL FROM DUAL
INSERT INTO TB_BOARD ( BOARD_ID, BOARD_TYPE_CD, BOARD_SJ, BOARD_CN, FRST_RGTR_ID, FRST_REG_DT, LAST_MDFR_DT, BOARD_ATCH_FILE_ID, DEPT_CD, PROJ_ID, IMPRTNT_YN, CMNT_USE_YN, VIEW_CNT, DEL_YN
) VALUES ( #{boardId}, #{boardTypeCd}, #{boardSj}, #{boardCn}, #{frstRgtrId}, SYSDATE, SYSDATE, #{boardAtchFileId}, #{deptCd}, #{projId}, #{imprtntYn}, #{cmntUseYn}, 0, 'n' )


		SELECT SEQ_BOARD_COMMENT_ID.NEXTVAL FROM DUAL

	INSERT INTO TB_BOARD_COMMENT (
              COMMENT_ID
            , BOARD_ID
            , COMMENT_CN
            , WRTER_EMP_ID
            , WRTE_DT
            , COMMENT_PRT_ID
            , COMMENT_DEPTH
            , COMMENT_ORDER
            ,	DEL_YN
        ) VALUES (
              #{commentId}
            , #{boardId}
            , #{commentCn}
            , #{wrterEmpId}
            , SYSDATE
            , #{commentPrtId, jdbcType=NUMERIC} 
            , #{commentDepth}
            , #{commentOrder}
            ,'n'
        )

mapper.update:
UPDATE TB_BOARD_COMMENT
	SET COMMENT_CN = #{commentCn}
		, WRTE_DT = SYSDATE
	WHERE COMMENT_ID = #{commentId}
	AND WRTER_EMP_ID = #{wrterEmpId}

mapper.select:
SELECT WRTER_EMP_ID
  FROM TB_BOARD_COMMENT
 WHERE COMMENT_ID = #{commentId}

SELECT * FROM ( SELECT B.BOARD_ID AS boardId, B.BOARD_SJ AS boardSj, E.EMP_NM AS empNm, B.FRST_REG_DT AS frstRegDt FROM TB_BOARD B LEFT JOIN TB_EMPLOYEE E ON B.FRST_RGTR_ID = E.EMP_ID WHERE B.DEL_YN = 'n'
AND TRIM(B.DEPT_CD) = TRIM(#{deptCd})
AND B.BOARD_TYPE_CD = #{boardTypeCd}
ORDER BY B.FRST_REG_DT DESC, B.BOARD_ID DESC ) WHERE ROWNUM <= #{limit}
